import Foundation

/// The services around Lia on the sign-in screen (SignInOrbit). Brand marks from the
/// `simple-icons` package (CC0), viewBox 0 0 24 24, each path rewritten to absolute M L C Q Z (arcs as cubics, S/T as
/// C/Q, H/V as L) so `SVGPath.parse` reads it; the rewrite was checked pixel for pixel against the original at 240 px.
/// OpenAI, Slack and Canva were removed from simple-icons after 13.x: their marks come from 13.21.0.
/// Not in simple-icons at all: Meta Ads Manager (plain Meta).: the product's own files, image sets in
/// Resources/Assets.xcassets (`asset`, trimmed and squared at 256/512 px), replace the path for every mark shown on the
/// sign-in but Vercel; the simple-icons paths stay as a fallback. Logos that are filled shapes with their own
/// background fill the whole bubble (Canva, Instagram, Facebook, Stripe as the bubble itself; Higgsfield as its fill).
struct BrandMark: Equatable {
    let id: String
    let name: String
    /// The brand's colour (simple-icons' hex).
    let hex: UInt32
    /// Which simple-icons release the mark came from.
    let source: String
    /// The glyph, viewBox 24.
    let d: String
    /// The product's own logo file in Assets.xcassets, drawn instead of `d` (which is then empty, or a fallback).
    var asset: String? = nil
    /// The asset is a one-colour mark: drawn as a template, in `hex` (white in dark when too dark there, unless the
    /// bubble has its own fill).
    var template = false
    /// A logo that is a filled shape with its own background fills the WHOLE bubble. Higgsfield: the
    /// bubble's disc takes this colour (lime) and the black squiggle sits centred on it.
    var bubbleFill: UInt32? = nil
    /// Canva, Instagram, Facebook, Stripe: the logo (a filled disc or square) is drawn as the bubble itself, edge to edge.
    var fillsBubble = false
}

enum BrandMarks {
    static func mark(_ id: String) -> BrandMark? { all.first { $0.id == id } }

    /// The image sets the marks use (Resources/Assets.xcassets).
    static var assetNames: [String] { all.compactMap(\.asset) }

    /// A glyph too dark to read on a dark bubble (#1C1C1E): drawn white there (GitHub, Vercel, Notion, TikTok, OpenAI).
    static func needsLightGlyphOnDark(_ hex: UInt32) -> Bool {
        func lin(_ c: UInt32) -> Double {
            let v = Double(c & 0xFF) / 255
            return v <= 0.04045 ? v / 12.92 : pow((v + 0.055) / 1.055, 2.4)
        }
        let l = 0.2126 * lin(hex >> 16) + 0.7152 * lin(hex >> 8) + 0.0722 * lin(hex)
        return l < 0.06
    }

